parameters.jsonBody:
={{ JSON.stringify({
  keywords: ($json['Keywords'] || '').split(',').map(s => s.trim()).filter(Boolean),
  locations: ($json['Location'] || '').split(',').map(s => s.trim()).filter(Boolean),
  industries: ($json['Industry contains'] || '').split(',').map(s => s.trim()).filter(Boolean),
  companySizes: [].concat($json['Company sizes'] || []),
  headquartersIn: ($json['Headquarters in'] || '').split(',').map(s => s.trim()).filter(Boolean),
  maxCompanies: Math.min(Number($json['How many companies']) || 25, 40),
  includePosts: false
}) }}
